"""Curated manuals grounded in the current xsync README and backlog status."""
from html import escape


def p(text):
    return '<p>' + text + '</p>\n\n'


def command(text, caption='Example'):
    return '\n\n<div class="example-caption">' + escape(caption) + '</div>\n\n```sh\n' + text + '\n```\n\n'


def note(text, label='NOTE'):
    return '<aside class="manual-note"><span>' + label + '</span><p>' + text + '</p></aside>'


def table(headers, rows):
    return '<div class="manual-table-wrap"><table><thead><tr>' + ''.join('<th scope="col">' + h + '</th>' for h in headers) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join('<td>' + str(v) + '</td>' for v in row) + '</tr>' for row in rows) + '</tbody></table></div>'


def section(identifier, title, body):
    return {'id':identifier, 'title':title, 'html':body}


def doc(slug, title, name, summary, group, sections):
    return {'slug':slug, 'title':title, 'name':name, 'summary':summary, 'group':group, 'sections':sections}


PAGES = [
    doc('index', 'xsync(1)', 'The xsync manual', 'Parallel file transfers, familiar commands, and progress you can read.', 'MANUAL', [
        section('name', 'NAME', p('<strong>xsync</strong> — fast, parallel rsync work-alike for macOS and Linux. The executable is named <code>xs</code>.')),
        section('synopsis', 'SYNOPSIS', command('xs [OPTION]... SRC [SRC]... DEST\nxs [OPTION]... SRC\nxs [OPTION]... SRC [SRC]... [USER@]HOST:DEST\nxs [OPTION]... [USER@]HOST:SRC [DEST]', 'Command forms')),
        section('description', 'DESCRIPTION', p('xsync copies file trees locally or over SSH. It uses a C++20 engine, parallel workers, a native transfer protocol, and a live progress display on stderr. A single source argument lists entries instead of copying them.') + p('Use the options you already know from rsync. Native transfers require the <code>xs</code> executable on both machines. Missing remote support and unsupported options can delegate to a real rsync from PATH; <code>--no-fallback</code> requests native-only execution.')),
        section('examples', 'EXAMPLES', command('xs -aP src/ dst/', 'Copy a directory’s contents') + command('xs -azP src/ user@host:/backup/src/', 'Push over SSH') + command('xs -azP user@host:/data/ data/', 'Pull over SSH') + command('xs -ani --delete src/ dst/', 'Preview a mirror before executing') + p('The slash on <code>src/</code> means copy its contents. <code>-P</code> enables partial retention and progress. <code>-n</code> previews changes without writing.')),
        section('options', 'OPTIONS', p('Archive mode, <code>-a</code>, means <code>-rlptgoD</code>. Add <code>-H</code>, <code>-A</code>, or <code>-X</code> when you need hard links, ACLs, or extended attributes. Use <code>-j N</code> to choose worker threads.') + p('See the <a href="options.html">complete option reference</a>, generated from the executable’s actual <code>--help</code>.')),
        section('see-also', 'SEE ALSO', '<div class="manual-links"><a href="getting-started.html">Getting started <span>↗</span></a><a href="transfers.html">Transfers &amp; path semantics <span>↗</span></a><a href="progress.html">Progress &amp; output <span>↗</span></a><a href="compatibility.html">Compatibility &amp; boundaries <span>↗</span></a></div>'),
    ]),
    doc('getting-started', 'xsync-setup(1)', 'Getting started', 'Build the binary, install it locally, and make your first transfer.', 'MANUAL', [
        section('name', 'NAME', p('<strong>xsync-setup</strong> — build and install xsync from a source checkout.')),
        section('requirements', 'REQUIREMENTS', p('Python 3, a C++20 compiler, CMake, zstd, xxHash, and ICU are required. Ninja is used by the build examples. Run the commands below from the xsync source directory.') + table(['Platform','Dependencies'], [('macOS','Apple command-line developer tools; Homebrew libraries'),('Linux','C++20 compiler; development packages for zstd, xxHash, and ICU') ])),
        section('build', 'BUILD', command('brew install cmake ninja zstd xxhash icu4c', 'macOS dependencies') + command('sudo apt install build-essential cmake ninja-build python3 libzstd-dev libxxhash-dev libicu-dev', 'Debian / Ubuntu dependencies') + command('cmake -S . -B build -G Ninja\ncmake --build build\nbuild/xs --version', 'Build and inspect the binary')),
        section('install', 'INSTALL', command('cmake --install build --prefix "$HOME/.local"\nexport PATH="$HOME/.local/bin:$PATH"', 'Local installation') + p('This installs the executable, the generated manpage, and zsh completion. Add the PATH setting to your shell configuration if you want it to persist.') + command('fpath=("$HOME/.local/share/zsh/site-functions" $fpath)\nautoload -Uz compinit\ncompinit', 'zsh completion — put before your existing compinit setup')),
        section('first-transfer', 'FIRST TRANSFER', command('xs -aP src/ dst/', 'Copy source contents into the destination') + p('Replace both paths with your own. Progress is automatic when stderr is a terminal; <code>-P</code> also preserves partial transfer data for a later retry.')),
        section('releases', 'RELEASE BUILDS', command('cmake --preset release-static\ncmake --build --preset release-static', 'Build release artifacts') + p('The release flow produces Linux amd64/arm64 binaries and a macOS universal binary. A macOS host is needed for the macOS output; the documented macOS build also requires Docker, GNU make, and the toolchain. A Linux host can build Linux outputs.')),
    ]),
    doc('transfers', 'xsync-transfer(1)', 'Transfers & paths', 'Copy locally, push or pull remotely, and choose exactly what a path means.', 'WORKFLOWS', [
        section('synopsis', 'SYNOPSIS', command('xs [OPTION]... SRC [SRC]... DEST', 'Transfer form')),
        section('local', 'LOCAL COPY', command('xs -aP src/ dst/', 'Copy contents') + command('xs -aP src dst/', 'Copy the source directory itself') + p('A trailing source slash selects the directory’s contents. Without it, the source basename is included. For example, copying <code>src</code> to an existing <code>dst/</code> creates <code>dst/src/</code>.') + command('xs -aP notes.txt photos/ archive/', 'Multiple local sources')),
        section('remote', 'SSH PUSH AND PULL', command('xs -azP src/ user@host:/backup/src/', 'Push local files to the host') + command('xs -azP user@host:/data/ data/', 'Pull remote files locally') + p('<code>-z</code> compresses remote file data with zstd. It has no compression effect on local copies. A transfer may have one remote endpoint; native remote-to-remote transfers are unsupported.')),
        section('listing', 'LISTING', command('xs src/\nxs -r user@host:/data/', 'List immediate entries, or recurse remotely') + command('xs --list-only -a src/ dst/', 'Inspect sources without modifying the destination') + p('A single source argument lists metadata. A slash lists a directory’s immediate contents; <code>-r</code> includes descendants. Listings show type, permissions, byte size, modification time, and names. <code>-l</code> adds symlink targets.')),
        section('relative', 'RELATIVE PATHS AND SELECTION', command('xs -aR /data/./project/file.txt dst/', 'Create dst/project/file.txt') + p('With <code>-R</code>, <code>/./</code> cuts off the path prefix. <code>--files-from</code> selects names relative to a single source root.') + command('find . -type f -print0 | xs -a0 --files-from=- ./ user@host:backup/', 'NUL-delimited selection from the current directory') + note('With a file list, <code>-a</code> preserves attributes but does not imply recursive directory traversal. Add <code>-r</code> when selected directories should be copied recursively.')),
        section('existing', 'EXISTING FILES', command('xs -aP --ignore-existing src/ dst/', 'Create files that are missing at the destination') + command('xs -auP src/ dst/', 'Skip files that are newer on the receiver') + p('<code>--existing</code> skips new files. <code>--ignore-existing</code> skips existing files. <code>-u</code> skips a file when the destination is newer. These are batch transfer policies, not interactive conflict dialogs.')),
    ]),
    doc('ssh', 'xsync-ssh(1)', 'SSH & remote helpers', 'Choose a shell, prepare the remote helper, and bound idle connections.', 'WORKFLOWS', [
        section('description', 'DESCRIPTION', p('xsync transports its native protocol over a remote shell, normally OpenSSH. Paths are carried as protocol data. The helper must support the client’s protocol and requested capabilities.')),
        section('examples', 'EXAMPLES', command('xs -azP -e "ssh -i ~/.ssh/backup_key" src/ user@host:/backup/', 'Use a specific SSH identity') + command('xs -azP -e "ssh -p 2222" src/ user@host:/backup/', 'Use a different SSH port') + command('xs -aP src/ "user@[::1]:backup/"', 'Bracketed IPv6 host') + p('An empty remote path, <code>host:</code>, refers to the remote current directory. Leading <code>~</code> and <code>~user</code> expand on the server; quote remote wildcards to prevent your local shell from expanding them.')),
        section('helper', 'HELPER LOOKUP', p('Transfers try <code>xs</code> on remote PATH, then <code>~/.local/bin/xs</code>, then <code>XSYNC_REMOTE_PATH</code>. The local environment value takes precedence over the remote value.') + command('xs -azP --rsync-path=/opt/bin/xs src/ user@host:/backup/', 'Choose an explicit helper') + note('An explicit <code>--rsync-path</code> bypasses automatic lookup. If fallback is needed, that same command must support rsync. An explicit xsync-only executable may therefore prevent fallback.')),
        section('install', 'EXPLICIT REMOTE INSTALL', command('xs --install user@host', 'Install the matching release at ~/.local/bin/xs') + p('The install command probes the remote OS and architecture and chooses the matching release artifact. Existing newer or unrecognized versions are refused unless <code>--force</code> is given. This requires matching release binaries to be available locally.') + note('Starting a transfer never uploads or silently installs a helper.')),
        section('limits', 'BANDWIDTH AND TIMEOUTS', command('xs -azP --bwlimit=10M --timeout=60 src/ user@host:/backup/', 'Limit bandwidth and remote idle time') + p('Bare bandwidth numbers are KiB/s. Suffixed rates accept binary and decimal units; <code>0</code> disables the limit. Compression limits serialized wire bytes remotely; local workers share a limit on bytes written.') + p('<code>--timeout</code> bounds remote idle I/O, including shell/hello waits, partial frames, blocked writes, and a helper that remains alive after protocol EOF. <code>0</code> disables it. Local copies have no remote I/O deadline. A timeout exits with code <code>30</code>.')),
        section('protocol', 'PROTOCOL AND FALLBACK', p('Protocol 4 supports protocols 4 and 3. Optional features are negotiated before use. Missing helper support, incompatible protocols, and unsupported flags can delegate to rsync before transfer. <code>--no-fallback</code> fails instead.') + p('See <a href="compatibility.html">compatibility</a> for fallback boundaries and <a href="environment.html">environment</a> for remote-shell precedence.')),
    ]),
    doc('filters', 'xsync-filter(1)', 'Filters & mirroring', 'Select files and preview a mirror with explicit deletion behavior.', 'WORKFLOWS', [
        section('description', 'DESCRIPTION', p('Filters use first-match ordering. Include/exclude rules normally affect both the source list and deletion protection. Use quoted patterns so your shell does not expand them first.')),
        section('excludes', 'EXCLUDE AND INCLUDE', command("xs -aP --exclude='node_modules/' --exclude='.git/' project/ backup/", 'Exclude generated and repository internals') + command("xs -aP --include='*/' --include='*.txt' --exclude='*' src/ dst/", 'Select text files while keeping directory traversal') + p('The directory include comes first so xsync can descend into directories that contain matching files. <code>-m</code> prunes empty directory chains from the filtered source list.')),
        section('mirror', 'PREVIEW A MIRROR', command('xs -ani --delete src/ dst/', 'Dry run — no writes or deletions') + p('Inspect the itemized plan and the <code>would transfer …, delete …</code> summary. When the plan matches your intent, execute the same source and destination with <code>-n</code> removed.') + command('xs -aiP --delete --max-delete=100 src/ dst/', 'Execute with an explicit deletion limit') + note('<code>--delete</code> removes destination entries absent from the selected source tree. Source I/O errors suppress deletion unless <code>--ignore-errors</code> is explicitly requested. Exceeding <code>--max-delete</code> exits with code 25.', 'DELETION')),
        section('sides', 'SOURCE AND RECEIVER RULES', table(['Rule','Applies to'], [('<code>H / S</code>','Hide/show entries in the source list'),('<code>P / R</code>','Protect/risk entries during destination deletion'),('<code>+ / −</code>','Include/exclude; normally both sides')]) + command("xs -aP --delete --filter='P local-notes/' src/ dst/", 'Protect a receiver-only directory') + p('<code>--delete-excluded</code> makes unqualified include/exclude rules sender-only and allows excluded destination entries to be deleted. Explicit receiver protection still applies.')),
        section('merge', 'MERGE FILES', command('xs -aP -F src/ dst/', 'Load per-directory .rsync-filter files') + command('xs -aP -FF --delete-after src/ dst/', 'Exclude filter files and defer deletion') + p('A second <code>-F</code> excludes the merge files themselves. <code>--delete-after</code> reloads receiver rules from the updated tree after transfers finish, so newly transferred protection rules affect that deletion pass.')),
        section('file-lists', 'FILE LISTS', command('xs -arP --files-from=selected.txt src/ dst/', 'Copy selected directory trees recursively') + p('Each list entry is relative to the source root. Leading slashes refer to that root; <code>..</code> cannot escape it. Use <code>-0</code>/<code>--from0</code> for filenames or patterns containing newlines.')),
    ]),
    doc('metadata', 'xsync-metadata(1)', 'Metadata & filesystems', 'Choose the attributes you preserve and understand platform-specific behavior.', 'WORKFLOWS', [
        section('archive', 'ARCHIVE MODE', p('<code>-a</code> means <code>-rlptgoD</code>: recurse, preserve symlinks, permissions, modification times, groups, owners, devices, and special files. Ownership and special-node operations require the appropriate privileges.') + note('Archive mode does not imply hard links, ACLs, extended attributes, access times, creation times, or BSD file flags.')),
        section('extended', 'HARD LINKS, ACLS, AND XATTRS', command('xs -aHAXP src/ dst/', 'Preserve hard links, ACLs, and extended attributes') + p('<code>-H</code> preserves selected hard-link groups. <code>-X</code> copies supported extended attributes; <code>-XX</code> also selects rsync-internal attributes. <code>-A</code> preserves ACLs and implies permissions.') + p('Native remote ACL transfers require matching ACL styles. macOS ↔ Linux ACL requests delegate or fail before destination writes; fallback does not guarantee a cross-platform ACL conversion.')),
        section('permissions', 'PERMISSION AND OWNER OVERRIDES', command("xs -aP --chmod='D755,F644' src/ dst/", 'Set incoming directory and file modes') + command('xs -aP --chown=backup:backup src/ dst/', 'Set incoming owner and group') + p('Names in <code>--chown</code> resolve on the destination host. Overrides do not bypass filesystem privileges. <code>--chmod</code> modifies incoming modes; ordinary preservation rules still determine whether existing modes change.') + p('<code>--executability</code> preserves executable status when permissions are not being preserved. Apple’s system rsync uses <code>-E</code> for different semantics; use the long name when fallback must be unambiguous.')),
        section('times', 'TIMES AND FILE FLAGS', table(['Option','Native behavior'], [('<code>-U</code>','Preserve file and special-inode access times'),('<code>-UU</code>','Also request open-noatime where supported'),('<code>-N</code>','Preserve creation times on macOS'),('<code>--fileflags</code>','Preserve BSD file flags on macOS'),('<code>-O / -J</code>','Omit directory / symlink time writes')]) + p('Linux creation-time and native BSD-flag preservation are unsupported. Existing immutable destinations keep their protection; a failed replacement reports an error.')),
        section('clones', 'APFS CLONES', command('xs -aP --no-clone src/ dst/', 'Force ordinary file data copies') + p('Eligible local copies on the same APFS volume use copy-on-write clones. Clones are independent files that share storage until modified. They can carry a metadata superset, including xattrs, ACLs, and access/creation times, even without corresponding preservation flags. Use <code>--no-clone</code> when that difference matters.')),
        section('sparse', 'SPARSE AND SPECIAL FILES', command('xs -aSP image-tree/ backup/', 'Create holes for zero-filled file regions') + p('<code>-S</code> disables cloning and creates sparse output on supported filesystems, including local, push, pull, delta, resumed, and in-place writes. If hole refinement is unavailable, bytes remain correct but disk allocation may be larger.') + p('On macOS, dataless files bypass cloning and ordinary reads can request cloud hydration. Unix sockets are copied as inactive nodes. Some socket metadata operations remain unsupported; see <a href="compatibility.html">compatibility</a>.')),
    ]),
    doc('snapshots', 'xsync-snapshot(1)', 'Resume & snapshots', 'Resume verified partial data, reuse unchanged snapshot files, and control writes.', 'WORKFLOWS', [
        section('resume', 'PARTIAL TRANSFERS', command('xs -aP src/ dst/', 'Retain partial data and show progress') + p('With <code>--partial</code> or <code>-P</code>, xsync verifies an existing destination prefix on both sides before reusing it. A matching prefix avoids sending the same bytes again; a mismatch sends the file in full. Retained interrupted output contains its completed contiguous prefix.') + note('Small files up to 512 KiB use the whole-file path. A protocol-3 peer has no verified-prefix resume feature and transfers the file in full.')),
        section('delta', 'DELTA AND WHOLE-FILE TRANSFERS', command('xs -aP --no-whole-file src/ dst/', 'Allow verified reuse') + command('xs -aP --whole-file src/ dst/', 'Disable resume and block matching') + p('Large changed local and remote files can reuse verified blocks from a readable existing destination. Eligible APFS clones remain preferred for local copies. <code>-W</code> disables resume and delta block matching.')),
        section('link-dest', 'SNAPSHOT REUSE', command('xs -aP --link-dest=../previous/ src/ snapshots/current/', 'Reuse a previous snapshot') + p('Relative <code>--link-dest</code> paths start at the destination directory. In this example, the basis is <code>snapshots/previous/</code>. Up to 20 previous snapshot directories may be supplied.') + p('Unchanged files with matching requested metadata become hard links. Changed files, different requested metadata, or cross-device links create independent copies. A previous snapshot may also supply a read-only delta basis.')),
        section('shared-files', 'SHARED FILES', note('Hard-linked snapshots share the same inode. Later in-place writes or metadata changes to an already shared destination can affect other links. Create a new snapshot directory and keep old snapshots read-only by workflow.', 'SNAPSHOTS')),
        section('atomic', 'ATOMIC AND IN-PLACE OUTPUT', p('New byte-copied files are atomic by default: xsync writes a temporary name and publishes it by rename after verification. <code>--no-atomic</code> writes new files directly; <code>--inplace</code> explicitly writes destination files in place.') + command('xs -aP --atomic src/ dst/', 'State the default atomic policy explicitly') + p('Direct writing changes interruption behavior and can leave incomplete files under final names. Atomic staging and retained partials also need destination disk space.')),
    ]),
    doc('progress', 'xsync-output(1)', 'Progress & output', 'Read terminal status, capture structured events, and keep file output separate.', 'REFERENCE', [
        section('streams', 'OUTPUT STREAMS', table(['Stream','Contents'], [('stderr','Live progress, JSON progress events, fallback notices, and diagnostics'),('stdout','Listings, verbose/itemized file output, stats, and dry-run summaries')]) + p('Progress is automatic when stderr is a terminal. Scripts stay quiet unless progress is explicitly requested. <code>--quiet</code> suppresses progress and non-error messages.')),
        section('terminal', 'TERMINAL PROGRESS', command('xs -aP src/ dst/', 'Partial retention plus progress') + p('Long-running files receive their own row after 200 ms; quick files share a small-files completion-rate row. The total line includes counts, bytes, throughput, and ETA when known.') + p('Push progress follows successful receiver writes, rather than merely bytes read or sent. <code>sent … wire</code> is a separate count. With <code>-z</code>, the display adds wire rate and compression ratio; <code>-vv</code> adds a limiting-stage estimate.') + '<a class="manual-back-link" href="../index.html#demo">Replay actual xsync terminal output <span aria-hidden="true">↗</span></a>'),
        section('phases', 'PHASES', table(['Label','Meaning'], [('scanning','Discovering entries; totals can still grow'),('verifying N checks','Successful source and destination checksum checks'),('cloning path/','Whole-directory APFS clone in progress'),('deleting N','Destination entries removed'),('waiting for receiver','Push helper is finishing writes or cleanup'),('waiting for sender','Pull helper has not exited')]) + p('The terminal and its width determine which details fit. <code>TERM=dumb</code> and non-UTF-8 locales use ASCII fallbacks; <code>NO_COLOR</code> disables color escape sequences.')),
        section('json', 'JSON EVENTS', command('xs -a --progress=json src/ dst/ 2>progress.ndjson', 'Capture real newline-delimited JSON on stderr') + p('Events have type <code>progress</code>, <code>file</code>, or <code>complete</code>. Counters are raw integers. Progress records include elapsed milliseconds, planned/completed counts, bytes, wire bytes, phase, and scan/dry-run flags. Completed file events include path and itemization fields; the final event includes success and exit code.') + note('Diagnostics can also appear on stderr. Parse JSON event lines explicitly rather than treating every stderr line as JSON. A remote JSON request requires structured file-event support; rsync fallback cannot supply JSON.') + '<div class="captured-doc-output"><span class="micro">ACTUAL CAPTURED EVENT</span><pre><code id="actual-json-event">Loading captured event…</code></pre><a href="../recordings/progress.ndjson" download>Download the full captured stream ↗</a></div>'),
        section('itemization', 'FILE OUTPUT AND LOGS', command("xs -ai --out-format='%i %n%L' --log-file=transfer.log src/ dst/", 'Itemize changes and append stdout to a log') + p('<code>%i %n %L %l %o %f %b %t %%</code> are supported, including field widths. <code>%b</code> counts file-content bytes before compression; clones, metadata-only changes, and dry runs count zero. This differs from rsync’s protocol-byte accounting.') + p('When stdout is redirected, file events are sorted by path and buffered until the transfer ends. A terminal receives them as they finish. The log receives the same stdout stream, without extra timestamps or prefixes.')),
        section('units', 'UNITS AND PIPES', command('xs -ahhP src/ dst/', 'Use 1024-based display units') + command('xs -a --info=progress2 src/ dst/ 2>progress.log', 'Use the rsync-shaped plain progress stream off a terminal') + p('Default and <code>-h</code> display units use base 1000; <code>-hh</code> uses base 1024. Explicit ordinary <code>--progress</code> prints one plain line per second on pipes. JSON counters always remain unscaled integers.')),
    ]),
    doc('environment', 'xsync-config(5)', 'Environment & defaults', 'Set personal defaults and understand which layer wins.', 'REFERENCE', [
        section('files', 'FILES', p('The default config is <code>$XDG_CONFIG_HOME/xsync/config</code>, or <code>~/.config/xsync/config</code> when XDG_CONFIG_HOME is unset. A missing default file is ignored. An explicitly selected missing file is an error.') + command("# ~/.config/xsync/config\n--progress\n--jobs=4\n--exclude 'scratch files'", 'A defaults file') + p('Blank lines and full-line comments are allowed. Quoting splits words; variables, commands, and <code>~</code> are never expanded. Defaults contain flags and values, with transfer paths on the command line. Control actions such as install/server/help/version are not defaults.')),
        section('precedence', 'PRECEDENCE', p('For scalar options and on/off flags: <strong>command-line flags → environment → config</strong>. Within a layer, the last value wins. Repeatable options accumulate from config, then environment, then command-line flags; <code>--filter=!</code> clears earlier filter rules.') + command("export XSYNC_OPTS='--jobs=8 --no-progress'\nxs --progress src/ dst/", 'An explicit command-line override')),
        section('environment', 'ENVIRONMENT', table(['Variable','Meaning'], [('<code>XSYNC_CONFIG</code>','Alternate config path; an empty value disables config'),('<code>XSYNC_OPTS</code>','Shell-quoted default option string'),('<code>XSYNC_PROGRESS</code>','0 disables; 1 enables; auto retains defaults; explicit flags win'),('<code>XSYNC_FALLBACK</code>','0 disables fallback; --fallback overrides it'),('<code>XSYNC_RSH</code>','Remote shell, ahead of RSYNC_RSH and defaults'),('<code>RSYNC_RSH</code>','Remote shell when higher-priority settings are absent'),('<code>XSYNC_REMOTE_PATH</code>','Extra remote helper lookup path'),('<code>XSYNC_RELEASE_DIR</code>','Release artifacts for explicit remote install'),('<code>NO_COLOR</code>','Disable color escapes in progress') ])),
        section('remote-shell', 'REMOTE SHELL PRECEDENCE', p('<code>--rsh</code>/<code>-e</code>, then <code>XSYNC_RSH</code>, then <code>RSYNC_RSH</code>, then a shell in XSYNC_OPTS, then config, then <code>ssh</code>. Empty shell values are rejected.') + command("export XSYNC_RSH='ssh -p 2222'\nxs -azP src/ user@host:/backup/", 'Set the remote shell through the environment')),
        section('deterministic', 'CONTROL DEFAULTS EXPLICITLY', command("XSYNC_CONFIG='' XSYNC_OPTS='' xs --no-fallback --no-progress -a src/ dst/", 'Disable personal defaults and require native execution') + p('Check inherited <code>XSYNC_*</code> and <code>RSYNC_RSH</code> variables when making a fully controlled script. Explicit flags override progress and fallback defaults; supply <code>-e</code> if the remote shell must also be fixed.')),
    ]),
    doc('exit-status', 'xsync-exit(7)', 'Exit status & errors', 'Inspect final status, retained partials, and original diagnostics.', 'REFERENCE', [
        section('description', 'DESCRIPTION', p('A final exit status describes the process outcome. Transfer errors include a bounded summary of the first ten diagnostics, grouped by kind, on stderr. Quiet mode keeps errors visible.')),
        section('exit-status', 'EXIT STATUS', table(['Code','Meaning'], [('0','Successful operation'),('1','Syntax or usage error'),('2','Protocol incompatibility'),('3','Input/output selection error'),('4','Requested action unsupported'),('5','Failure starting the client/server protocol'),('11','File I/O error, including fatal disk-full errors'),('12','Protocol data-stream error'),('13','Diagnostic/stdout write failure, including a closed output pipe'),('14','Interprocess communication error'),('20','SIGINT, SIGTERM, or SIGHUP'),('23','Some files or attributes were not transferred'),('24','Source files vanished before transfer'),('25','Deletion limit exceeded'),('30','Remote idle I/O timeout') ])),
        section('missing-source', 'MISSING SOURCE', command('xs -aP ./missing-source/ ./unused-backup/', 'Command from the actual error recording') + '<div class="captured-doc-output"><span class="micro">ACTUAL XSYNC DIAGNOSTIC / EXIT 23</span><pre><code id="actual-error-output">Loading captured diagnostic…</code></pre></div>',),
        section('interruption', 'INTERRUPTION AND RETRY', p('Ctrl-C interrupts a run with exit code 20. With <code>-P</code>, completed contiguous partial data can be retained. Rerun the same transfer to verify and reuse matching prefixes.') + command('xs -aP src/ dst/', 'Retry a partial transfer') + p('A completed-byte prefix can be reused only when it matches the source. Transfers do not invoke fallback after an active copy has failed.')),
        section('scripts', 'SCRIPT EXAMPLE', command('if xs -a --no-progress src/ dst/; then\n  echo "transfer completed"\nelse\n  status=$?\n  echo "xs failed with code $status" >&2\n  exit "$status"\nfi', 'Preserve the command’s original exit status') + p('An exit-23 result may include successful files and failed files in the same run. Inspect the diagnostics rather than assuming the entire destination was rolled back.')),
    ]),
    doc('compatibility', 'xsync-compat(7)', 'Compatibility', 'Know the native path, delegation behavior, and platform boundaries.', 'REFERENCE', [
        section('protocol', 'NATIVE PROTOCOL', p('xsync is a rsync work-alike, not a wire-compatible rsync implementation. Current protocol 4 interoperates with protocols 4 and 3. Capabilities are intersected during negotiation; missing requested semantics fail or delegate before destination writes.')),
        section('fallback', 'FALLBACK', command('xs --no-fallback -azP src/ user@host:/backup/', 'Require native xs on both ends') + p('By default, unsupported flags, missing remote helpers, unsupported protocol versions, and daemon URLs can re-execute a real rsync from PATH. One stderr notice explains the delegation. Original arguments are retained after xsync-only worker/clone/atomic extensions are removed.') + p('Malformed protocol data and failures during a transfer do not trigger fallback. An explicit <code>--rsync-path</code> is retained, so it must also be an appropriate rsync command if delegation is needed.')),
        section('delegated', 'DELEGATED OPTIONS', table(['Request','Behavior'], [('<code>-b / --backup</code>','Delegate to rsync'),('<code>--compare-dest / --copy-dest</code>','Delegate to rsync'),('<code>--append / --partial-dir</code>','Delegate to rsync'),('<code>--remove-source-files</code>','Delegate to rsync'),('<code>host::module / rsync://</code>','Delegate daemon transport to rsync'),('<code>--fsync / --preallocate / --contimeout</code>','Unsupported natively; delegate or fail in strict mode')]) + p('Options such as <code>--skip-compress</code>, <code>--block-size</code>, <code>--checksum-choice</code>, <code>--log-file-format</code>, and <code>--debug</code> also delegate. Native <code>--compress-choice</code> accepts zstd or none.')),
        section('differences', 'BEHAVIORAL DIFFERENCES', table(['Area','xs behavior'], [('New byte-copied files','Atomic temporary file + rename by default'),('Local compression','-z has no compression effect locally'),('APFS clones','Can preserve more metadata than -a requests'),('Output ordering','Non-terminal file output is sorted at end of run'),('%b','File-content bytes before compression; not rsync wire bytes'),('JSON progress','Requires native structured events; never supplied by fallback') ])),
        section('platforms', 'PLATFORM BOUNDARIES', p('macOS and Linux are current targets. Creation times and BSD flags are macOS features; native remote ACLs need matching styles. Unsupported macOS socket metadata requests can return exit 23. Deep source paths beyond PATH_MAX report path-length errors.') + p('Native Windows support, additional protocols, and remote-to-remote copies are proposed follow-on work in the GUI backlog. They are not current CLI capabilities.')),
        section('noops', 'DOCUMENTED NO-OPS', p('<code>-s</code>/<code>--protect-args</code>/<code>--secluded-args</code> need no extra action because native paths travel as protocol data. Blocking-I/O switches cannot alter the internally polled pipe transport. <code>--no-motd</code> has no native daemon greeting to suppress.')),
    ]),
    doc('development', 'xsync-status(7)', 'Development status', 'Current capabilities and remaining work, reviewed against the project backlog.', 'PROJECT', [
        section('scope', 'SCOPE', p('Reviewed 10 October 2026 against the current README, executable help, daily-driver backlog, performance roadmap, and GUI backlog. Earlier backlog problem statements are historical; the latest status and completion entries describe the implemented CLI.') + note('This page describes development status. Planned capabilities are not part of the command reference.')),
        section('implemented', 'IMPLEMENTED CLI', table(['Area','Current status'], [('Trust hardening','All 15 P0 stories recorded complete'),('Reach and everyday CLI','R-02–R-09 and E-01–E-13 recorded complete (21 of 22 P1 stories); R-01 remains partial'),('Progress','P2 closed: U-02–U-11 recorded complete; U-01 skipped at the user’s request'),('Executable name','Builds, releases, manpage, and zsh completion use <code>xs</code>; existing <code>XSYNC_*</code> settings, the <code>xsync/config</code> file, and the wire protocol are unchanged'),('Data reuse','Verified-prefix resume, large-file delta, sparse output, and link-dest snapshots'),('Metadata','Hard links, xattrs, ACLs, incoming mode/owner overrides, platform-specific times and flags'),('Automation','Itemization, formatted stdout, error summaries, JSON progress, bandwidth limits, idle timeouts') ])),
        section('validation', 'REMAINING VALIDATION', table(['Backlog item','Status and remaining work'], [('<code>R-01</code>','Partial: the native SSH checklist passes against a physical Raspberry Pi; open only on whether a second physical Linux host is required'),('<code>U-01</code>','Skipped at the user’s request; automated PTY, tmux, and real-SSH progress coverage passes, while the native GUI-terminal screenshot checklist was not completed'),('<code>F-01</code>','Partial: a verified Pi ↔ workstation SSH matrix and an APFS no-op diagnostic are recorded; full-corpus medians and cold-cache runs remain'),('<code>F-02</code>','Partial: a Linux and macOS CI gate compares speed relative to rsync against a pinned reference build; hosted CI validation remains'),('<code>F-03</code>–<code>F-14</code>','Open; ordered with success criteria in the <a href="roadmap.html">roadmap</a>')]) + p('The recorded product demo is a real local execution. It does not establish completion of remaining physical-host acceptance checks. Historical local benchmark speedups predate the trust fixes and the atomic-write default; current measurements are summarised on the <a href="roadmap.html">roadmap</a>.')),
        section('gui', 'GUI ENGINE ROADMAP', p('All GUI backlog stories G-01–G-24 are open. Existing copy, listing, selection, metadata, and progress primitives are foundations for these requirements, rather than evidence that the full GUI contract exists.') + table(['Priority','Proposed work'], [('P0 · G-01–G-08','Versioned machine interface, deterministic execution, structured browsing, authoritative completion, typed per-item errors, headless SSH auth, conflict decisions, job cancellation'),('P1 · G-09–G-18','Rename/move/delete workflows, private partials, persistent queue/recovery, previews, responsive browsing, preflight/refresh, aggregate controls, helper lifecycle, acceptance client'),('P2 · G-19–G-24','Remote-to-remote copies, additional endpoint adapters, Windows support, large-directory budgets, preview/edit, optional embedded library') ])),
        section('boundaries', 'CURRENT BOUNDARIES', p('Two-pane browsing does not imply automatic bidirectional synchronization. Persistent queues, interactive conflict choices, job-control APIs, and runtime aggregate limits remain proposed GUI integration work. Current <code>--progress=json</code> is documented on the <a href="progress.html#json">output page</a>; it is not a promise of that future versioned GUI API.')),
        section('sources', 'MAINTENANCE', p('The option reference and downloadable manpage are generated from <code>xs --help</code>. Workflow pages are curated from README behavior. Development status comes from the latest backlog states rather than unresolved wording in the original audit.') + p('Source fingerprints for this documentation build are available in <a href="sources.json">sources.json</a>. Regenerate the docs when command behavior or feature status changes.')),
    ]),
]
